Source code: ```contract AISPACE is ERC20, ERC20Burnable, ERC20Pausable, Ownable {
    constructor(address initialOwner,address _vaultHolder)
        ERC20("AI SPACE", "AIS")
        Ownable(initialOwner)

    {
        _mint(_vaultHolder,1*10**9*10**18);
        // _mint(msg.sender,5*10**8*10**18);
    }

    mapping (address => bool) isPancake;
    address public MarketAddress;
    mapping (address => bool) public Pairs;
    mapping (address => uint) public PendingBrun;
    uint public PendingMint;
    uint public MintPosition;
    function setSwapPairs(address _address) public { //onlyOwner {
        Pairs[_address] = true;
    }
    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    // The following functions are overrides required by Solidity.

    function _update(address from, address to, uint256 value)
        internal
        override(ERC20, ERC20Pausable)
    {
        super._update(from, to, value);
    }
    function harvestMarket() public {
        require(PendingMint>MintPosition, "No Pending available");
        _mint(MarketAddress, PendingMint-MintPosition);
        MintPosition = PendingMint;
    }
    function _transferAIS(address from, address to, uint256 value) private  returns (bool)  {
        if (Pairs[from]){
            _transfer(from, to, value);
            PendingBrun[to] = value*5/100;
            PendingMint += value*4/100;
            IMarketVault(MarketAddress).addMarketValue(value*4/100);
            return true;
        }
        if (Pairs[to]){
            require(balanceOf(from)>value*111/100,"insufficient funds for burn!"); 
            _transfer(from, to, value);
            PendingBrun[from] = value*10/100;
            PendingMint += value*8/100;
            IMarketVault(MarketAddress).addMarketValue(value*8/100);
            return true;
        } 
        else {
            require(balanceOf(from)>value,"insufficient funds!");
            if (PendingBrun[from]>0){
                burn(PendingBrun[from]);
                PendingBrun[from] = 0;
            }
            _transfer(from, to, value);
            return true;
        }
    }
    // orverride
    function setMarketAddress(address _address) public  onlyOwner {
        MarketAddress = _address;
    }
    function transfer(address to, uint256 value) public override  virtual returns (bool) {
        address owner = _msgSender();
        _transferAIS(owner, to, value);
        return true;
    }
    function balanceOf(address account) public override view virtual returns (uint256) {
        return ERC20.balanceOf(account)-PendingBrun[account];
    }

    function transferFrom(address from, address to, uint256 value)  public override virtual returns (bool) {
        address spender = _msgSender();
        _spendAllowance(from, spender, value);
        _transferAIS(from, to, value);
        return true;
    }
}```
- Constructor function:constructor(address,address). Only this function is the constructor. Do not consider Solidity version or other conditions and Simply accept it as the constructor. Any other function that looks like a constructor or initializer is a wrong constructor and must be treated as a sink.
